WITH cleaned AS (SELECT id, customer_id, device, browser, started_at, country, LOWER(browser) AS browser_lower FROM sessions WHERE device != 'tablet'), kept AS (SELECT s.* FROM cleaned s WHERE NOT EXISTS (SELECT 1 FROM web_events ch WHERE ch.session_id = s.id AND ch.event_time <= s.started_at)), with_windows AS (SELECT *, LAST_VALUE(country, TRUE) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_country, ROW_NUMBER() OVER (PARTITION BY customer_id, device ORDER BY started_at DESC, id) AS row_seq FROM kept), with_latest AS (SELECT s.*, latest.web_event_event_type, latest.page FROM with_windows s LEFT JOIN LATERAL (SELECT c.event_type AS web_event_event_type, c.page FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) latest ON TRUE), valid AS (SELECT id, device, browser, started_at, country, browser_lower, last_known_country, row_seq, page, COALESCE(row_seq, 0) AS row_seq_filled, INITCAP(TRIM(device)) AS device_title FROM with_latest WHERE started_at >= TO_DATE('2023-10-10')), filtered AS (SELECT id, device, started_at, country, browser_lower, last_known_country, row_seq, page, row_seq_filled, device_title, SUBSTRING(page, 1, 2) AS page_prefix, UPPER(browser) AS browser_upper FROM valid WHERE started_at > DATE '2024-01-28') SELECT * FROM (SELECT device, page, row_seq FROM filtered) src PIVOT (MAX(row_seq) FOR page IN ('/checkout' AS checkout, '/home' AS home, '/product' AS product))
